function useSentence(set, kind, u, who){
  const nm = list => list.map(it => esc(itemName(it)));
  const v = (lead, third) => (who ? '<b class="m">' + esc(who) + '</b> ' : '') + '<b class="uv" role="button" tabindex="0" data-rule="Select Weapons">' + (who ? third : lead) + '</b>';
  if(kind === 'ranged'){
    const cq = set.filter(isCQ), rest = set.filter(it => !isCQ(it)), big = hasKw(u, 'Monster') ? 'MONSTER' : hasKw(u, 'Vehicle') ? 'VEHICLE' : '';
    // 24.07: one or more [CLOSE-QUARTERS] weapons, or one or more of the others (not MONSTER/VEHICLE models)
    const some = l => l.length > 1 ? 'one or more of ' + andList(nm(l)) : nm(l)[0];
    const cqLink = linkTo('rule', 'Close-quarters', 'Close-quarters');
    if(cq.length && rest.length && !big)
      return v('Can shoot with', 'can shoot with') + ' ' + some(cq) + ' <b>or</b> ' + some(rest) + ', not both (' + cqLink + '); in close-quarters shooting, ' + andList(nm(cq)) + ' only.';
    const guns = modelCount(u) === 1 ? set.reduce((t, it) => t + (+it.n || 1), 0) : set.length;   // a Forgefiend's 2 Hades + 1 cannon
    const w = guns === 2 ? 'one or both' : 'one or more of these';
    return v('Can shoot with ' + w, 'can shoot with ' + w) + (cq.length && rest.length ? ' (' + cqLink + ' does not limit ' + big + ' models)' : '') + '.';
  }
  // (melee: an [EXTRA ATTACKS] weapon is no choice, its keyword on its row says it is used too (24.11): only the pick is said)
  const other = set.filter(it => !isEA(it));
  return other.length > 1 ? v('Pick one to fight with:', 'picks one to fight with:') + ' ' + orList(nm(other)) + '.' : '';
}

function useLine(items, kind, u, who){
  if(items.length < 2 || !u.gear) return '';
  // in an attached unit, only the models lines of the part that carries these (a character, or the bodyguard)
  const own = i => who == null || whoOfLine(u, i) === who;
  const mine = u.gear.map((g, i) => i).filter(own);   // every models line of this part, with these weapons or not
  // a line's name without " w/…", unless another line shares it (Tankbusta w/ Two Busta Rokkit Launchas)
  const short = i => u.models[i].replace(/^\d+× /, '').replace(/ w\/.*$/, '');
  const nameOf = i => mine.some(j => j !== i && short(j) === short(i)) ? u.models[i].replace(/^\d+× /, '') : short(i);
  // a model with two of one weapon has it twice in its set
  const lines = mine.map(i => ({ i, who:nameOf(i), set:items.flatMap(it => Array(u.gear[i].filter(x => x === itemName(it)).length).fill(it)) })).filter(l => l.set.length);
  const everyLine = lines.length === mine.length;   // "every model" / "per model" only when every models line has some
  const none = everyLine ? '' : '<p class="use"><b class="m">' + andList(mine.filter(i => !lines.some(l => l.i === i)).map(i => esc(nameOf(i)))) + ':</b> none of these.</p>';
  // (melee: its [EXTRA ATTACKS] weapons are no choice, their keyword says they are used too: a line with one other weapon has none)
  const multi = lines.filter(l => (kind === 'melee' ? l.set.filter(it => !isEA(it)) : l.set).length > 1);
  // a weapon only one model has, in a squad of mixed loadouts: name that model (the champion's pistol)
  if(lines.length > 1) for(const it of items){ const ls = lines.filter(l => l.set.includes(it)); if(!it.n && !it.carrier && ls.length === 1 && /^1× /.test(u.models[ls[0].i]) && ls[0].set.filter(x => x === it).length === 1) it.carrier = short(ls[0].i); }
  if(!multi.length){
    if(lines.length < 2) return none;
    for(const it of items){ const ls = lines.filter(l => l.set.includes(it)); if(!it.n && ls.length === 1) it.carrier = short(ls[0].i); }   // name the one models line that has it
    return '<p class="use"><b class="m">' + (everyLine ? 'One of these per model' : 'At most one of these per model') + '</b> · ×N = how many the unit has.</p>' + none;
  }
  const key = l => (kind === 'melee' ? l.set.filter(it => !isEA(it)) : l.set).map(itemName).join('|');
  if(everyLine && multi.length === lines.length && multi.every(l => key(l) === key(multi[0]))) return '<p class="use">' + useSentence(multi[0].set, kind, u) + '</p>';
  const others = multi.length < lines.length;
  if(kind === 'ranged' && !others && everyLine && multi.every(l => /data-rule="Select Weapons">Can shoot with one or (both|more of these)/.test(useSentence(l.set, kind, u))))
    return '<p class="use"><b class="uv" role="button" tabindex="0" data-rule="Select Weapons">Every model can shoot with one or more of its guns</b>.</p>';
  // one sentence per models line that has several (two lines with the same pair are both named)
  return multi.map(l => '<p class="use">' + useSentence(l.set, kind, u, l.who) + '</p>').join('') +
    (others ? '<p class="use"><b class="m">The others:</b> one each (×N = how many the unit has).</p>' : '') + none;
}

function weaponChoice(items, kind, u, who){
  if(!u.gear) return false;
  const own = i => who == null || whoOfLine(u, i) === who;
  const lines = u.gear.map((g, i) => i).filter(own).map(i => items.filter(it => u.gear[i].includes(itemName(it))));
  const short = i => u.models[i].replace(/^\d+× /, '').replace(/ w\/.*$/, '');
  // a weapon only one models line of one model has, in a squad of mixed loadouts: that model's name on its row (the weapon tells which one)
  const mine = u.gear.map((g, i) => i).filter(own), has = mine.map(i => ({ i, has:items.filter(it => u.gear[i].includes(itemName(it))) })).filter(l => l.has.length);
  const choice = kind === 'ranged' ? !(hasKw(u, 'Monster') || hasKw(u, 'Vehicle')) && lines.some(l => l.some(isCQ) && l.some(it => !isCQ(it))) : lines.some(l => l.filter(it => !isEA(it)).length > 1);
  // (with a choice, the sentence names the models: useLine)
  if(!choice && has.length > 1) for(const it of items){ const ls = has.filter(l => l.has.includes(it)); if(!it.n && !it.carrier && ls.length === 1 && /^1× /.test(u.models[ls[0].i])) it.carrier = short(ls[0].i); }
  return choice;
}

function unitMods(u, kind){
  const A = army(), out = [], srcs = dmSources(A, u);
  const of = g => srcs.filter(S => S.grp === g);
  const core = [];
  // (Lance for its [LANCE] weapons; Plunging Fire for a TOWERING unit, not AIRCRAFT: BOXES played, the Damage tab's own)
  const played = (name, text) => { const key = DM_KEY.c(name, text), o = BOXES_AGREED[key]; return o && o.played ? { grp:'unit', name, rule:name, key, core:true } : null; };
  if([].concat(u.ranged || [], u.melee || []).some(w => (w.kw || []).some(k => /^lance$/i.test(k))) && D.rules.Lance) core.push(played('Lance', D.rules.Lance));
  if(hasKw(u, 'Towering') && !hasKw(u, 'Aircraft') && D.rules['Plunging Fire']) core.push(played('Plunging Fire', D.rules['Plunging Fire']));
  const dmg = (u.abilities || []).filter(ab => /^Damaged: /i.test(ab.name)).map(ab => ({ grp:'unit', name:ab.name, key:DM_KEY.a(ab), ab, src:u, damaged:true }));
  // (the core stratagems, every unit's, are on the Stratagems tab: the footnotes name the list's detachments' stratagems)
  const listStrat = S => !S.strat || (S.s && S.s.src !== 'Core');
  // (the order of the lines, docs/summaries.md 40: army-wide (army and detachment rules), the unit's own (its abilities, enhancement,
  // wargear, Damaged bands, its weapons' core abilities), other units' auras and grants, stratagems; GW's order within each)
  for(const S of of('army').concat(of('unit').filter(S => !S.core), dmg, of('unit').filter(S => S.core).map(S => Object.assign({ rule:S.name }, S)), core.filter(Boolean), of('other'), of('strat')).filter(listStrat)){
    const o = BOXES_AGREED[S.key] || {};
    let fell = false; const fellOpts = [];
    for(const b of o.b || []){
      if(S.reachOnly ? !(b.reach && dmReaches(b.reach, u)) : b.reach ? !dmReaches(b.reach, u) || (S.grp === 'unit' && b.notSelf) : S.grp === 'other') continue;
      if(b.kind !== 'all' && b.kind !== kind) continue;
      // (a box the two-reader rule does not confirm, effects.js agreed: where it would have been a footnote, for this kind of attack and
      // these weapons, its rule's words not counted)
      if(b.unconfirmed){ if(fnReaches(S, b, u, kind)){ fell = true; fellOpts.push(...boxOpts(b, S.name)); } continue; }
      const m = fnLine(S, b, u, kind, S.ab);
      if(m) out.push(m);
    }
    // (words about its attacks no catalogue effect reads, BOXES nc atk: "not counted here: see the rule", the name opening them; not
    // another unit's words (they may not reach this one), not a Damaged band's (its band says so). And a box of it the two-reader rule
    // does not confirm, where it reaches: another unit's too, with the unit it is from, "not counted here: see the rule (Tech-Priest Enginseer)")
    const giver = S.grp === 'other' ? fnGiver(S, u) : '';
    // (drawn as ncHtml: a rule's name alone, else its name and its short summary, another unit's "Granted by")
    if(!S.damaged && (fell || (S.grp !== 'other' && (o.nc || []).some(x => x.atk && !x.unconfirmed))) && !out.some(x => x.key === S.key && x.ncLine)) out.push(Object.assign({ kind:'all', when:'', note:FN_NC + (giver ? ' (' + giver + ')' : ''), who:'', from:S.name, key:S.key, box:null, ncLine:true, short:srcShort(S, 'atk'), opts:[...new Set(fellOpts)] }, S.core ? { core:true } : {},
      S.rule ? { rule:S.rule } : {}, S.strat ? { strat:S.strat, cp:S.cp } : {}, S.src && S.src !== u ? { src:S.src, giver } : S.ab && S.ab.who && u.leads && charsOf(u).some(c => c.name === S.ab.who) ? { leader:S.ab.who } : {}));
  }
  return out;
}

function fnLine(S, b, u, kind, ab){
  const E = WH_EFFECTS, sc = b.scope || {};
  // (a weapon keyword it excludes names its weapons only where one of the unit's has it)
  const ws0 = sc.weapon || sc.wkw || sc.part || sc.wkwNot ? fnWeapons(u, kind, sc) : null;
  const ws = ws0 && !sc.weapon && !sc.wkw && !sc.part && ws0.length === weaponItems(kind === 'ranged' ? u.ranged || [] : u.melee || []).length ? null : ws0;
  if(ws && !ws.length) return null;   // (for weapons this kind of attack has not)
  // (not an effect the list printed into the weapons, marked + there; nor a weapon ability every weapon it reaches has already: Waaagh!'s
  // [ASSAULT] for a unit whose ranged weapons all have it)
  const its = ws || weaponItems(kind === 'ranged' ? u.ranged || [] : u.melee || []);
  const hasAll = l => /^\[.+\]$/.test(l) && its.length && its.every(it => it.profiles.every(w => (w.kw || []).some(k => '[' + String(k).toUpperCase() + ']' === l)));
  // (nor, for melee attacks, an effect only ranged attacks have: range, a set BS, [ASSAULT], [HEAVY], [INDIRECT FIRE], [PISTOL])
  const baked = S.baked || [], keep = fx => (fx || []).filter(([id, p]) => !dmBaked(baked, id, p) && !hasAll(E.fxLabel([[id, p]])) && !(kind === 'melee' && FN_RANGED.has(id)));
  // (a keyword or wargear of the unit the box needs, "If this model has the TOZEENTCH keyword": the unit's keywords and weapons say it)
  const wn = [].concat(u.ranged || [], u.melee || []).flatMap(w => [w.name, w.group]).filter(Boolean).map(x => String(x).toLowerCase());
  if((b.on || []).some(([id, p]) => (id === 'selfKw' && !hasKw(u, p)) || (id === 'selfGear' && !p.every(g => wn.some(n => n.startsWith(String(g).toLowerCase())))))) return null;
  // (the unit that gives it: its name, or the model of an attached unit whose ability it is)
  const gab = S.src && S.src !== u ? (S.src.abilities || []).find(x => x.name === S.name) : null;
  const giver = S.src && S.src !== u ? (gab && gab.who && S.src.leads && charsOf(S.src).some(c => c.name === gab.who) ? gab.who : S.src.short || S.src.name) : '';
  const own = S.grp === 'unit' && b.mark === 'aura';
  // (none: every attack of its kind; a stratagem's line names it with its cost instead)
  // (a stratagem's one phase, from its derived phases and turn: "Your Shooting phase", "Fight phase", the detachment's line says it once)
  const sPh = S.s && (S.s.phases || []).length === 1 ? (T => (T === 'your' ? 'Your ' : T === 'opp' ? 'Your opponent’s ' : '') + PHASE_NAME[S.s.phases[0]] + ' phase')(phTurn(S.s, S.s.phases[0])) : '';
  // (its conditions, each said; one that is only GW's words, quoted, is said too beside another, so the line is never wider than GW's
  // rule. A box whose only conditions are quoted says "If (see the rule)" (FN_IF), the rule's name opening its words: the owner's
  // decision, 31 Oct, never shown as always on. "Every attack": no condition at all, in the box or its options)
  const quoted = ([id]) => !!(E.COND[id] && E.COND[id].quoted), on = b.on || [];
  const conds = on => (on || []).map(([id, p]) => fnCond(id, p, u, giver, own, b, S.src)).join(' · ');
  const onlyQ = on.length && on.every(quoted);
  const anyPickOn = (b.pick || []).some(p => (p.on || []).length || p.part);
  const when = [sPh, onlyQ ? FN_IF : conds(on)].filter(Boolean).join(', ') || (S.strat || anyPickOn ? '' : b.kind === 'ranged' ? 'Every ranged attack' : b.kind === 'melee' ? 'Every melee attack' : 'Every attack');
  const part = x => x && x.fx && x.fx.length ? ' (' + (conds(x.on) ? conds(x.on) + ': ' : '') + E.fxLabel(x.fx) + ')' : '';
  let note, fx = null;
  if(b.pick){ const ps = b.pick.map(p => Object.assign({}, p, { fx:keep(p.fx) })).filter(p => p.fx.length);
    if(!ps.length) return null;
    const bOn = new Set((b.on || []).map(x => JSON.stringify(x)));
    note = ps.map(p => { const pon = (p.on || []).filter(x => !bOn.has(JSON.stringify(x)));
      return (p.name !== E.fxLabel(p.fx) ? p.name + ': ' : '') + E.fxLabel(p.fx) + (conds(pon) ? ' (' + conds(pon) + ')' : '') + part(p.part); }).join(' · ');
    note = 'one of: ' + note; }
  else { fx = keep(b.fx); if(!fx.length) return null; note = E.fxLabel(fx) + part(b.part); }
  const who = ws ? [...new Set(ws.map(itemName))].join(', ') : sc.models === 'char' ? 'CHARACTER models' : sc.models === 'nonchar' ? 'Models (not CHARACTER)' : sc.models === 'one' ? 'One model' :
    sc.part ? sc.part + ' models' : sc.models === 'model' && ab && ab.who && u.leads ? ab.who : '';
  const m = { kind:b.kind, when, note, who, from:S.name, box:b, key:S.key, short:srcShort(S, 'atk') };
  if(S.core) m.core = true;
  if(S.rule) m.rule = S.rule;
  if(S.strat){ m.strat = S.strat; m.cp = S.cp; }
  if(S.src && S.src !== u){ m.src = S.src; m.giver = giver; }
  // (a leader's ability on the unit it leads: "Granted by: <leader>", docs/summaries.md 24)
  else if(S.ab && S.ab.who && u.leads && charsOf(u).some(c => c.name === S.ab.who)) m.leader = S.ab.who;
  if(S.damaged){ m.damaged = true; m.gw = gwPlain((S.ab || {}).text); }
  // a box for one weapon's characteristics, nothing else: that weapon's row shows it ("8 (+6)", "6/7"), its condition under it
  // (not a stratagem's, nor an ability's the unit uses, "if it uses this ability": the player's to use, as a one-off is: oneOffMod)
  if(fx && ws && ws.length === 1 && !ws[0].group && !S.damaged && !S.strat && !(b.on || []).some(x => x[0] === 'used') && fx.every(([id]) => FN_ROW[id] || FN_SET[id])){
    m.weapon = ws[0].profiles[0].name; m.set = Object.fromEntries(fx.map(([id, p]) => FN_ROW[id] ? [FN_ROW[id], '+' + String(p).toUpperCase()] : [FN_SET[id], String(p)])); m.note = ''; m.who = ''; }
  return m;
}

function fnCond(id, p, u, giver, own, b, gu){
  const C = WH_EFFECTS.COND[id];
  if(id === 'aura') return own ? 'Own aura' : giver ? 'Within ' + p + '" of ' + giver : C.label(p);
  if(id === 'selected' && giver) return 'Selected by ' + giver;
  if(id === 'targetSelected' && giver) return ['Target selected by ' + theGiver(giver, gu), FN_LASTS[(b || {}).lasts] || ''].filter(Boolean).join(' ');
  if(id === 'belowStarting' && modelCount(u) === 1) return 'Lost any wounds (' + C.label(p) + ')';
  if(id === 'belowHalf' && modelCount(u) === 1) return halfBelow(u) + ' or fewer wounds left (' + C.label(p) + ')';
  return C ? C.label(p) : id;
}

function defSources(u){
  const A = army(), F = factionOf(A) || {}, out = [], seen = new Set();
  const put = x => { if(seen.has(x.key + '|' + x.grp)) return; seen.add(x.key + '|' + x.grp); const o = defBoxesOf(x.key); if(o && (o.d || o.dnc)) out.push(Object.assign(x, { o })); };
  for(const r of F.armyRules || []){ const own = hasRule(u, r.name) || !!dmGrantOf(A, u, r.name), o = defBoxesOf(DM_KEY.r(r));
    const reach = !own && A.units.some(x => x !== u && hasRule(x, r.name)) && ((o || {}).d || []).some(b => b.reach && dmReaches(b.reach, u));
    if(own || reach) put({ grp:'army', name:r.name, a:'rule', v:r.name, key:DM_KEY.r(r), reachOnly:reach, holders:reach ? A.units.filter(x => hasRule(x, r.name)) : null }); }
  for(const r of unitDetRules(u)) put({ grp:'army', name:r.name, a:'rule', v:r.name, key:DM_KEY.r(r) });
  for(const ab of u.abilities || []) if(!naReason(ab)) put({ grp:'unit', name:ab.name, a:'ability', v:abilityKey(ab), key:DM_KEY.a(ab), ab, src:u });
  // (its Rules line's core rules with a value, Feel No Pain 5+: the unit's own, after its abilities, docs/summaries.md 40)
  for(const r of u.rules || []){ if(!/\d/.test(r) || D.rules[r]) continue; const t = dmCoreText(r); if(t) put({ grp:'core', name:r, a:'rule', v:r, key:DM_KEY.c(r, t), rl:r }); }
  for(const x of A.units) if(x !== u) for(const ab of x.abilities || []) if(!naReason(ab)) put({ grp:'other', name:ab.name, a:'unit', v:x.id, key:DM_KEY.a(ab), ab, src:x, abv:abilityKey(ab) });
  // (the core stratagems, every unit's, are on the Stratagems tab, as for the footnotes)
  for(const s of allStratagems().filter(s => s.src !== 'Core')){ const o = defBoxesOf(DM_KEY.s(s)); if(!o) continue;
    const mine = o.dreach ? matches(o.dreach, u) && A.units.some(x => x !== u && canTarget(s, x)) : canTarget(s, u);
    if(mine) put({ grp:'strat', name:s.name, a:'strat', v:s.id, key:DM_KEY.s(s), s, cp:s.cp }); }
  return out;
}

function defenceItems(u){
  const out = [];
  for(const S of defSources(u)){
    let fell = false;
    for(const b of S.o.d || []){
      // (a box given to friendly units: where it reaches this one; the unit's own for itself only where it is an aura, 22.01, not "other";
      // an enemy unit's attacks made worse: every unit of the list. Another unit's other boxes are its own)
      if(b.foe ? false : S.reachOnly ? !(b.reach && dmReaches(b.reach, u)) : b.reach ? !dmReaches(b.reach, u) || (S.grp === 'unit' && b.notSelf) : S.grp === 'other') continue;
      // (a box the two-reader rule does not confirm, effects.js agreed: where it would have been a line, its rule's words not counted)
      if(b.unconfirmed){ const wn = [].concat(u.ranged || [], u.melee || []).flatMap(w => [w.name, w.group]).filter(Boolean).map(x => String(x).toLowerCase());
        if(!(b.on || []).some(([id, p]) => ((id === 'selfKw' || id === 'itIs') && !hasKw(u, p)) || (id === 'selfGear' && !p.every(g => wn.some(n => n.startsWith(String(g).toLowerCase())))))) fell = true; continue; }
      // (an invulnerable save or Save characteristic the list printed into its stats, marked as from this rule, the other models' as good or
      // better already: Arcane Shield's 4+ InSv on its Rubric Marines, as a footnote leaves out what is in the weapons)
      const inStats = (k, p) => (u.stats || []).some(r => r.from && String(r.from[k] || '').split(/\s*,\s*/).includes(S.name)) && (u.stats || []).every(r => (r.from && String(r.from[k] || '').split(/\s*,\s*/).includes(S.name)) || parseInt(r[k], 10) <= p);
      const tIn = () => (u.stats || []).some(r => r.from && String(r.from.T || '').split(/\s*,\s*/).includes(S.name));
      if(!b.pick && b.df.length && b.df.every(([id, p]) => (id === 'inv' && inStats('InSv', p)) || (id === 'svSet' && inStats('Sv', p)) || (id === 't' && !(b.on || []).length && tIn()))) continue;
      const x = defLineOf(S, b, u); if(x) out.push(x);
    }
    // (its words about attacks against it no defence reads: "not counted here: see the rule", once; not another unit's)
    // (and a box of it the two-reader rule does not confirm, where it reaches: another unit's too, with the unit it is from)
    const giver = S.grp === 'other' ? (S.ab && S.ab.who && S.src.leads && charsOf(S.src).some(c => c.name === S.ab.who) ? S.ab.who : S.src.short || S.src.name) : '';
    // (drawn by defLine as a not-counted line is, ncHtml: a rule's name alone, else its name and short summary, another unit's "Granted by")
    if(fell || (S.grp !== 'other' && (S.o.dnc || []).some(x => !x.unconfirmed))) out.push({ a:S.a, v:S.v, name:S.name, cp:S.cp || '', who:S.ab && S.ab.who && u.leads && S.grp !== 'other' ? S.ab.who : '', when:'', text:FN_NC, from:giver, abv:S.abv, key:S.key, ncLine:true, short:ncShortOf(S), rl:S.rl || '', S });
  }
  // (a Feel No Pain on its Rules line that another of its lines says with its condition or its model: Aegis of the Emperor's "against mortal
  // wounds", New Recruit's starred "Feel No Pain 5+*"; Trajann's own: not said twice)
  const fnpOf = x => x.box ? (x.box.pick ? x.box.pick.flatMap(p => p.df) : x.box.df).filter(([id]) => /^fnp/.test(id)).map(([, p]) => p) : [];
  // (a Feel No Pain on its Rules line that another of its lines says with its words: one of its own abilities ("the bearer has the Feel No Pain
  // 3+ ability against Psychic Attacks", Collar of Khorne), or, for New Recruit's starred "Feel No Pain 5+*", any rule ("against mortal wounds",
  // Aegis of the Emperor): not said twice, never without its condition)
  // (New Recruit's starred one, "Feel No Pain 5+*", is its words not counted (effects.js DNC starred): not said where a rule of the unit says
  // that Feel No Pain with its condition)
  const starV = x => x.ncLine && x.rl && (/^feel no pain (\d)\+\*$/i.exec(x.rl) || [])[1];
  const res = out.filter(x => !(x.rl && /^feel no pain/i.test(x.rl) && (starV(x) ? [+starV(x)] : fnpOf(x)).some(v => out.some(y => y !== x && !y.rl && (y.a === 'ability' || /\*$/.test(x.rl)) && fnpOf(y).includes(v)))));
  // (the one model of an attached unit a rule of its Rules line is on: partialRules)
  for(const x of res) if(x.rl && !x.who){ const w = partialWho(u, x.rl); if(w) x.who = w; }
  // (a source with a summary is one line, its summary (sum); a rule's words not counted, its only lines here, its name (a blanket rule);
  // the source's other lines are that one line (dup), not drawn)
  const sums = new Set();
  for(const x of res){ x.blanket = x.a === 'rule' && !x.rl && !x.short && (menuRule(x.key) || res.every(y => y.key !== x.key || y.ncLine));
    x.sum = !!x.short && !x.rl;
    if(x.blanket){ const k = x.key + '\0b'; if(sums.has(k)) x.dup = true; sums.add(k); }
    if(x.sum){ x.opts = boxOpts(x.box, x.name); const k = x.key + '\0' + (x.from || '') + '\0' + (x.opts.join('|') || '-'); if(sums.has(k)) x.dup = true; sums.add(k); } }
  // (a leader's ability on the unit it leads: "Granted by: <leader>", docs/summaries.md 24)
  for(const x of res) if(x.sum && !x.from && x.who && charsOf(u).some(c => c.name === x.who)) x.leader = x.who;
  // (as defLine draws it: a rule's name alone; a summary for its words; another unit's "Granted by")
  for(const x of res){ if(x.blanket){ x.t = x.name; continue; }
    const text = x.sum ? x.short : x.ncLine ? x.short || FN_NC : x.text;
    if(x.sum){ x.t = x.from || x.leader ? 'Granted by: ' + (x.from || x.leader) + ' - ' + (!x.from && modelOnly(x, u) ? x.leader + ' only: ' : '') + text + ' (' + x.name + ')' : x.cp ? x.cp + 'CP ' + x.name + ': ' + stratLead((x.S || {}).s) + text : text + ' (' + x.name + ')'; continue; }
    x.t = (x.rl && !x.when && x.text === x.name) || (x.ncLine && x.a === 'rule' && !x.short) ? x.name : x.from ? ['Granted by: ' + x.from + ' -', x.when ? x.when + ':' : '', text, '(' + x.name + ')'].filter(Boolean).join(' ')
      : x.ncLine ? [x.cp ? x.cp + 'CP' : '', text, '(' + x.name + ')'].filter(Boolean).join(' ') : [x.cp ? x.cp + 'CP' : '', x.name + ':', x.when ? x.when + ':' : '', text].filter(Boolean).join(' '); }
  return res;
}

function defLineOf(S, b, u){
  const E = WH_EFFECTS, on = b.on || [], wn = [].concat(u.ranged || [], u.melee || []).flatMap(w => [w.name, w.group]).filter(Boolean).map(x => String(x).toLowerCase());
  // (a keyword or wargear of the unit the box needs: the unit's keywords and weapons say it)
  if(on.some(([id, p]) => ((id === 'selfKw' || id === 'itIs') && !hasKw(u, p)) || (id === 'selfGear' && !p.every(g => wn.some(n => n.startsWith(String(g).toLowerCase())))))) return null;
  const giver = S.grp === 'other' ? (S.ab && S.ab.who && S.src.leads && charsOf(S.src).some(c => c.name === S.ab.who) ? S.ab.who : S.src.short || S.src.name)
    : S.holders ? 'a unit with ' + S.name : '';
  const own = S.grp === 'unit' && b.mark === 'aura';
  const said = ([id, p]) => E.DCOND[id] ? E.DCOND[id].label(p) : fnCond(id, p, u, giver, own, b, S.src);
  const quoted = ([id]) => !!(E.COND[id] && E.COND[id].quoted);
  const ph = S.s && (S.s.phases || []).length === PHASES.length ? 'Any phase' : S.s && (S.s.phases || []).length ? S.s.phases.map((p, i) => (T => (T === 'your' ? 'Your ' : T === 'opp' ? 'Your opponent’s ' : i ? 'the ' : '') + PHASE_NAME[p] + ' phase')(phTurn(S.s, p))).join(' or ') : '';
  const df = b.pick ? b.pick.flatMap(p => p.df) : b.df;
  const kind = DEF_KIND[b.kind] && !defKindSaid(df, b.kind) ? DEF_KIND[b.kind] : '';
  // (every condition said; a box whose only conditions are GW's words, quoted, says "If (see the rule)", as a footnote does)
  const cond = on.length && on.every(quoted) ? FN_IF : on.map(said).join(' · ');
  const when = [ph, kind, cond].filter(Boolean).join(', ');
  const sc = b.scope || {}, models = sc.models && sc.models !== 'model' ? sc.models + ' models: ' : '';
  // (how long it lasts where its words say it lasts beyond the phase: "until the start of your next Command phase")
  const text = models + (b.pick ? 'one of: ' + b.pick.map(p => E.dfLabel(p.df)).join(' · ') : E.dfLabel(b.df)) + (b.until ? ' (' + b.until + ')' : '');
  return { a:S.a, v:S.v, name:S.name, cp:S.cp || '', who:S.ab && S.ab.who && u.leads && S.grp === 'unit' ? S.ab.who : '', when, text, from:S.grp === 'other' ? giver : '', abv:S.abv, riled:on.some(x => x[0] === 'riled'), box:b, key:S.key, rl:S.rl || '', short:srcShort(S, 'def'), foeOwn:S.grp === 'unit' && !!b.foe && !!S.ab, S };
}

function defLine(x, u){
  const who = x.who ? '<i class="sc">' + esc(x.who) + '</i> ' : '';
  const ar = x.riled && alwaysRiled(u), when = x.when ? esc(x.when) : '';
  const w = ar ? when.replace(/^(.*?)Riled up/, (m, pre) => pre + 'Riled up (' + ar + ')') : when;
  // (a rule of its Rules line that is its defence, "Feel No Pain 5+": its name)
  if(x.rl && !w && x.text === x.name) return who + '<b>' + linkTo(x.a, x.v, x.name) + '</b>';
  // (a rule whose words are not counted here: its name alone; another source's: its short summary, AI-labelled, opening its rule: ncHtml)
  if(x.blanket || (x.ncLine && x.a === 'rule' && !x.short)) return who + linkTo(x.a, x.v, x.name);
  // (what opens its rule: another unit's ability its rule, not that unit, which its "Granted by" opens)
  const ra = x.abv ? 'ability' : x.a, rv = x.abv || x.v, text = x.sum || x.ncLine ? ncSum([ra, rv], x.short) : esc(x.text);
  // (the always-riled note after the line's "(name)", never read as part of the AI text)
  const rn = x.sum ? riledNote(u, [x]) : '';
  // (a source's summary: its conditions are in it)
  if(x.from) return who + grantedBy(x.a === 'unit' ? { id:x.v } : null, x.from, x.name) + (w && !x.sum ? '<span class="tw">' + w + ':</span> ' : '') + text + ' <span class="from">(' + linkTo(ra, rv, x.name) + ')</span>' + rn;
  // (a stratagem: "<cp>CP <name>: <summary> AI"; another source: "<summary> AI (<name>)")
  if(x.cp && (x.ncLine || x.sum)) return who + '<b class="cpb">' + esc(x.cp) + 'CP</b> <b>' + linkTo(x.a, x.v, x.name) + ':</b> ' + stratLead((x.S || {}).s) + text + rn;
  if(x.leader) return grantedBy({ id:u.id }, x.leader, x.name) + modelOnly(x, u) + text + ' <span class="from">(' + linkTo(x.a, x.v, x.name) + ')</span>' + rn;
  if(x.ncLine || x.sum) return who + text + ' <span class="from">(' + linkTo(x.a, x.v, x.name) + ')</span>' + rn;
  return who + (x.cp ? '<b class="cpb">' + esc(x.cp) + 'CP</b> ' : '') + '<b>' + linkTo(x.a, x.v, x.name) + ':</b> ' + (w ? '<span class="tw">' + w + ':</span> ' : '') + text;
}

function screenPregame(){
  const a = army(), f = faction(), units = a.units;
