function statLines(u){
  const E = WH_EFFECTS, out = [];
  for(const r of faction().armyRules.concat(detachments().flatMap(detRules))) for(const b of (BOXES_AGREED[DM_KEY.r(r)] || {}).st || []){
    if(!(b.reach ? matches(b.reach, u) : r.needs && matches(r.needs, u))) continue;
    const on = b.on || [], onlyQ = on.length && on.every(([id]) => E.COND[id] && E.COND[id].quoted);
    const when = onlyQ ? FN_IF : on.map(([id, p]) => stCond(id, p, u)).join(' · ');
    for(const [id, p] of b.st){ const f = E.ST[id]; if(!f) continue;
      if(u.stats.every(s => [].concat((s.from || {})[f.stat] || []).join(', ').split(/\s*,\s*/).includes(r.name))) continue;
      // (not where an ability of the unit can set that characteristic to a value, Singular Purpose's "an Objective Control characteristic of 15":
      // then the effect, "+2 OC", never a total the unit may not have)
      const sets = (u.abilities || []).some(ab => new RegExp('\\ban? ' + f.name + ' characteristic of \\d', 'i').test(String(ab.text || '').replace(/\*\*/g, '')));
      const vs = [...new Set(u.stats.map(s => s[f.stat]))], one = !sets && !(b.scope || {}).models && vs.length === 1 && (f.inch ? /^\d+"$/ : /^\d+$/).test(String(vs[0]));
      const val = one ? f.stat + ' ' + ((parseInt(vs[0], 10) || 0) + f.add(p)) + (f.inch ? '"' : '') : ((b.scope || {}).models ? (b.scope.models + ' models ') : '') + f.label(p);
      out.push({ rule:r.name, text:(when ? when + ': ' : '') + val }); }
  }
  // (and the words of its sources that change a characteristic no stat box counts, BOXES snc: its abilities', an aura's of another unit of
  // the list that reaches it (Time Flux), its army and detachment rules', the stratagems it can be the target of: "M: not counted here: see
  // the rule", never silent; not one the list printed into the value, its from mark)
  const said = new Set();
  // (each where its words reach: the friendly units it names (its reach; else, for a rule, the units that have it: its needs, as a stat box),
  // a keyword of the unit it needs (on selfKw), "while this model is leading a unit" only on a unit that leads one (on leading))
  // (another unit's: an aura, its ability's tag or the option of it the entry is, "Binharic Courage (Aura)" of Canticles of the Omnissiah)
  const snc = (key, name, link, v, needs, gu, aura) => { for(const x of (BOXES_AGREED[key] || {}).snc || []){
    if(gu && !aura && !/\(Aura\)/.test(x.quote || '')) continue;
    if(x.reach ? !matches(x.reach, u) : needs !== undefined && !(needs && matches(needs, u))) continue;
    if((x.on || []).some(([id, p]) => (id === 'selfKw' && !hasKw(u, p)) || (id === 'leading' && !u.leads))) continue;
