          return sorted(row, order[kind] || []);
        });
      });
      READ.forEach(function(kind){ var l = readings(a, u, out, ids, parts, kind); if(l.length) out[kind] = l; });
      return sorted(out, order.unit || []);
    }) });
  });
}
